import math

def ndcg_at_k(ranked, gains, k):
    """ranked: ids best first. gains: id -> relevance (missing = 0)."""
    dcg = sum(gains.get(d, 0) / math.log2(i + 2) for i, d in enumerate(ranked[:k]))
    ideal = sorted(gains.values(), reverse=True)[:k]
    idcg = sum(g / math.log2(i + 2) for i, g in enumerate(ideal))
    return dcg / idcg if idcg > 0 else 0.0

def minmax(scores):
    """Rescale a dict of scores to [0, 1]: best -> 1, worst -> 0."""
    if not scores:
        return {}
    lo, hi = min(scores.values()), max(scores.values())
    if hi == lo:
        return {d: 1.0 for d in scores}
    return {d: (s - lo) / (hi - lo) for d, s in scores.items()}

def fuse(dense, keyword, alpha):
    """alpha * dense + (1 - alpha) * keyword, after min-max; a missing score counts as 0."""
    nd, nk = minmax(dense), minmax(keyword)
    ids = set(nd) | set(nk)
    return {d: alpha * nd.get(d, 0.0) + (1 - alpha) * nk.get(d, 0.0) for d in ids}

def rank(scores):
    return sorted(scores, key=lambda d: (-scores[d], d))

# Three labelled queries: each has dense and BM25 scores, and the gain of each relevant passage.
QUERIES = [
    {"dense": {"p1": 0.82, "p3": 0.78, "p2": 0.40}, "keyword": {"p3": 14.0, "p4": 6.0},
     "gains": {"p3": 3}},                       # an error-code question: keyword search is sure
    {"dense": {"p5": 0.91, "p6": 0.55}, "keyword": {"p7": 9.0, "p5": 7.0, "p6": 2.0},
     "gains": {"p5": 3}},                       # a paraphrased question: meaning is sure
    {"dense": {"p8": 0.70, "p9": 0.69, "p10": 0.20}, "keyword": {"p9": 11.0, "p8": 2.0},
     "gains": {"p9": 3}},                       # both half-see it; the blend decides
]

def best_alpha(queries, alphas, k=3):
    best, best_score = None, -1.0
    for alpha in alphas:
        scores = [ndcg_at_k(rank(fuse(q['dense'], q['keyword'], alpha)), q['gains'], k) for q in queries]
        mean = sum(scores) / len(scores)
        if mean > best_score:
            best, best_score = alpha, mean
    return best, best_score
